1	package warranty
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	var (
12		t0       = time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
13		day      = 24 * time.Hour
14		nowOK    = t0.Add(10 * day)
15		expiryOK = t0.Add(60 * day)
16	)
17	
18	func newStore(t *testing.T) *Store {
19		t.Helper()
20		s := NewStore()
21		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
22			t.Fatalf("register product: %v", err)
23		}
24		if err := s.RegisterPart("part1", 10); err != nil {
25			t.Fatalf("register part: %v", err)
26		}
27		if err := s.SubmitRequest("r1", "p1", "FAULTY"); err != nil {
28			t.Fatalf("submit request: %v", err)
29		}
30		return s
31	}
32	
33	func TestReadyStillTrue(t *testing.T) {
34		if !Ready() {
35			t.Fatal("baseline not ready")
36		}
37	}
38	
39	func TestRegisterDuplicatesAndValidation(t *testing.T) {
40		s := NewStore()
41	
42		if err := s.RegisterProduct("p1", t0, 30, nil); err != nil {
43			t.Fatalf("register product: %v", err)
44		}
45		if err := s.RegisterPart("part1", 5); err != nil {
46			t.Fatalf("register part: %v", err)
47		}
48		if err := s.SubmitRequest("r1", "p1", "FAULTY"); err != nil {
49			t.Fatalf("submit request: %v", err)
50		}
51	
52		// 重复登记一律报错，原记录保留。
53		if err := s.RegisterProduct("p1", t0, 30, nil); !errors.Is(err, ErrDuplicateID) {
54			t.Fatalf("duplicate product: got %v, want ErrDuplicateID", err)
55		}
56		if err := s.RegisterPart("part1", 5); !errors.Is(err, ErrDuplicateID) {
57			t.Fatalf("duplicate part: got %v, want ErrDuplicateID", err)
58		}
59		if err := s.SubmitRequest("r1", "p1", "FAULTY"); !errors.Is(err, ErrDuplicateID) {
60			t.Fatalf("duplicate request: got %v, want ErrDuplicateID", err)
61		}
62		// 原记录未被覆盖。
63		if p, err := s.Product("p1"); err != nil || p.WarrantyDays != 30 {
64			t.Fatalf("original product changed: %+v, err %v", p, err)
65		}
66	
67		// 非法参数。
68		if err := s.RegisterProduct("", t0, 30, nil); !errors.Is(err, ErrInvalidParam) {
69			t.Fatalf("empty product id: got %v", err)
70		}
71		if err := s.RegisterProduct("p2", t0, 0, nil); !errors.Is(err, ErrInvalidParam) {
72			t.Fatalf("zero warranty days: got %v", err)
73		}
74		if err := s.RegisterProduct("p3", t0, -1, nil); !errors.Is(err, ErrInvalidParam) {
75			t.Fatalf("negative warranty days: got %v", err)
76		}
77		if err := s.RegisterPart("", 1); !errors.Is(err, ErrInvalidParam) {
78			t.Fatalf("empty part id: got %v", err)
79		}
80		if err := s.RegisterPart("part2", -1); !errors.Is(err, ErrInvalidParam) {
81			t.Fatalf("negative stock: got %v", err)
82		}
83		if err := s.SubmitRequest("", "p1", "F"); !errors.Is(err, ErrInvalidParam) {
84			t.Fatalf("empty request id: got %v", err)
85		}
86		if err := s.SubmitRequest("r2", "p1", ""); !errors.Is(err, ErrInvalidParam) {
87			t.Fatalf("empty fault code: got %v", err)
88		}
89	}
90	
91	func TestEvaluateEligible(t *testing.T) {
92		s := newStore(t)
93		e, err := s.Evaluate("r1", nowOK)
94		if err != nil {
95			t.Fatalf("evaluate: %v", err)
96		}
97		if !e.Eligible || len(e.Reasons) != 0 {
98			t.Fatalf("expected eligible, got %+v", e)
99		}
100		if e.WarrantyExpiry != t0.Add(30*day) {
101			t.Fatalf("warranty expiry = %v, want %v", e.WarrantyExpiry, t0.Add(30*day))
102		}
103	}
104	
105	func TestEvaluateExpiryBoundary(t *testing.T) {
106		s := newStore(t)
107		// 到期时刻之前一秒：仍合格。
108		if e, err := s.Evaluate("r1", t0.Add(30*day).Add(-time.Second)); err != nil || !e.Eligible {
109			t.Fatalf("1s before expiry: eligible=%v err=%v", e.Eligible, err)
110		}
111		// 到期时刻开始（等于）：算过保。
112		e, err := s.Evaluate("r1", t0.Add(30*day))
113		if err != nil {
114			t.Fatalf("evaluate: %v", err)
115		}
116		if e.Eligible || len(e.Reasons) != 1 || e.Reasons[0] != ReasonWarrantyExpired {
117			t.Fatalf("at expiry: got %+v", e)
118		}
119	}
120	
121	func TestEvaluateExcludedAndExpiredBothListed(t *testing.T) {
122		s := newStore(t)
123		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
124			t.Fatalf("submit: %v", err)
125		}
126		// 第 31 天：已过保，且故障代码被除外 → 两项原因。
127		e, err := s.Evaluate("rBad", t0.Add(31*day))
128		if err != nil {
129			t.Fatalf("evaluate: %v", err)
130		}
131		if e.Eligible || len(e.Reasons) != 2 {
132			t.Fatalf("expected two reasons, got %+v", e)
133		}
134		got := map[RejectionReason]bool{}
135		for _, r := range e.Reasons {
136			got[r] = true
