47			t.Fatalf("duplicate with different terms: got %v, want ErrDuplicateID", err)
48		}
49		// 原条款完整保留：购买时刻、天数、除外集合都不被新提交改动。
50		checkProductTerms(t, s, "p1", t0, 30, "FAULTX", "FAULTY")
51	}
52	
53	// 重复编号同时带有非法条款时，编号重复优先于参数校验：报 ErrDuplicateID
54	// 而不是 ErrInvalidParam，原记录不被清空或部分替换。
55	func TestDuplicateProductInvalidTermsStillDuplicate(t *testing.T) {
