125			t.Fatalf("evaluate: %v", err)
126		}
127		if e.Eligible || !containsReason(e.Reasons, ReasonFaultExcluded) {
128			t.Fatalf("original exclusion lost: %+v", e)
129		}
130		// 仅出现在新清单中的故障不能成为除外。
131		e, err = s.Evaluate("rNewOnly", at)
132		if err != nil {
133			t.Fatalf("evaluate: %v", err)
134		}
135		if !e.Eligible {
136			t.Fatalf("fault only in rejected new list must not exclude, got reasons %v", e.Reasons)
137		}
138	
139		// 较长的新期限（300 天）：登记同样被拒绝。
140		if err := s.RegisterProduct("p1", t0, 300, nil); !errors.Is(err, ErrDuplicateID) {
141			t.Fatalf("duplicate with longer term: got %v, want ErrDuplicateID", err)
