153			t.Fatalf("eligibility basis changed: %+v", e)
154		}
155	
156		// 按请求查看资格依据：同样显示原保修条款与对应拒绝原因。
157		view, err := s.RequestView("rPlain", later)
158		if err != nil {
159			t.Fatalf("request view: %v", err)
160		}
161		ve := view.Eligibility
162		if ve.Eligible || !containsReason(ve.Reasons, ReasonWarrantyExpired) {
163			t.Fatalf("view eligibility = %+v, want expired under original terms", ve)
164		}
165		if ve.WarrantyDays != 30 || !ve.PurchaseTime.Equal(t0) || !ve.WarrantyExpiry.Equal(t0.Add(30*day)) {
166			t.Fatalf("view basis = (%v, %d, %v), want original terms",
167				ve.PurchaseTime, ve.WarrantyDays, ve.WarrantyExpiry)
168		}
169		view, err = s.RequestView("rExcluded", at)
170		if err != nil {
171			t.Fatalf("request view: %v", err)
172		}
173		if view.Eligibility.Eligible || !containsReason(view.Eligibility.Reasons, ReasonFaultExcluded) {
174			t.Fatalf("view for excluded fault = %+v", view.Eligibility)
175		}
176	}
177	
178	// 备件预留同样只认原条款：按原条款在保且未命中除外的请求，在库存足够、
179	// 承诺到期时刻晚于当前时刻时仍可预留；按原条款不合格的请求仍返回
180	// ErrIneligible，不生成承诺、不增加库存占用。重复登记失败不改动已有承诺
181	// 与已有预留历史中的资格依据。
182	func TestDuplicateRejectionKeepsReserveBehavior(t *testing.T) {
183		s := NewStore()
184		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
185			t.Fatalf("register product: %v", err)
186		}
187		if err := s.RegisterPart("part1", 10); err != nil {
188			t.Fatalf("register part: %v", err)
189		}
190		if err := s.SubmitRequest("rOK", "p1", "FAULTY"); err != nil {
191			t.Fatalf("submit: %v", err)
192		}
193		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
194			t.Fatalf("submit: %v", err)
195		}
196		// 重复登记失败前已有一笔成功预留。
197		if _, err := s.Reserve("c1", "rOK", "part1", 4, expiryOK, nowOK); err != nil {
198			t.Fatalf("reserve c1: %v", err)
199		}
200		// 重复登记失败：新期限更短、除外清单不同。
201		if err := s.RegisterProduct("p1", t0, 5, []string{"FAULTY"}); !errors.Is(err, ErrDuplicateID) {
202			t.Fatalf("duplicate: got %v, want ErrDuplicateID", err)
203		}
204	
205		// 按原条款在保的请求（即使故障代码出现在新清单中）仍可预留。
206		if _, err := s.Reserve("c2", "rOK", "part1", 4, expiryOK, nowOK); err != nil {
207			t.Fatalf("reserve after rejected duplicate: %v", err)
208		}
209		// 按原条款命中除外的请求仍不合格：不生成承诺、不增加占用。
210		if _, err := s.Reserve("c3", "rBad", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrIneligible) {
211			t.Fatalf("reserve for excluded fault: got %v, want ErrIneligible", err)
212		}
213		if _, err := s.Commitment("c3"); !errors.Is(err, ErrNotFound) {
214			t.Fatalf("rejected reserve must not create a commitment, got %v", err)
215		}
216		st, err := s.PartStatus("part1", nowOK)
217		if err != nil {
218			t.Fatalf("part status: %v", err)
219		}
220		if st.ActiveOccupied != 8 || st.Committable != 2 || st.PhysicalRemaining != 10 {
221			t.Fatalf("stock = phys %d occupied %d committable %d, want 10/8/2",
222				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
223		}
224	
225		// 已有承诺不被重复登记失败改动。
226		c1, err := s.Commitment("c1")
227		if err != nil {
228			t.Fatalf("commitment c1: %v", err)
229		}
230		if c1.Quantity != 4 || c1.Used != 0 || c1.Canceled || c1.Expired {
231			t.Fatalf("existing commitment changed: %+v", c1)
232		}
233	
234		// 已有预留历史中的资格依据仍显示原条款。
235		hist, err := s.RequestHistory("rOK")
236		if err != nil {
237			t.Fatalf("history: %v", err)
238		}
239		if len(hist) != 2 || !hist[0].Success || !hist[1].Success {
240			t.Fatalf("unexpected history: %+v", hist)
241		}
242		basis := hist[0].Eligibility
243		if basis == nil {
244			t.Fatal("first success record missing eligibility basis")
245		}
246		if basis.WarrantyDays != 30 || !basis.PurchaseTime.Equal(t0) || !basis.WarrantyExpiry.Equal(t0.Add(30*day)) {
247			t.Fatalf("history basis = (%v, %d, %v), want original terms",
248				basis.PurchaseTime, basis.WarrantyDays, basis.WarrantyExpiry)
249		}
250		// 不合格请求的失败记录也保留原条款依据与拒绝原因。
251		histBad, err := s.RequestHistory("rBad")
252		if err != nil {
253			t.Fatalf("history: %v", err)
254		}
255		if len(histBad) != 1 || histBad[0].Success || histBad[0].Error != HistoryErrorIneligible {
256			t.Fatalf("unexpected history for excluded request: %+v", histBad)
257		}
258		basis = histBad[0].Eligibility
259		if basis == nil || basis.WarrantyDays != 30 || !containsReason(basis.Reasons, ReasonFaultExcluded) {
260			t.Fatalf("rejected record basis = %+v, want original terms with fault_code_excluded", basis)
261		}
262	}
263	
264	// 区分重复编号和首次登记失败：尚未登记的非空编号提交非法条款时仍返回
265	// ErrInvalidParam，不留下产品记录；随后用同一编号提交合法条款正常登记。
266	func TestFirstRegistrationFailureThenValidRegistration(t *testing.T) {
267		s := NewStore()
268		invalid := []struct {
269			name  string
270			days  int
271			codes []string
272		}{
273			{"zero days", 0, nil},
274			{"negative days", -1, nil},
275			{"unrepresentable expiry", math.MaxInt, nil},
276			{"empty excluded code", 10, []string{""}},
277		}
278		for _, tc := range invalid {
279			err := s.RegisterProduct("pNew", t0, tc.days, tc.codes)
280			if !errors.Is(err, ErrInvalidParam) {
281				t.Fatalf("%s: got %v, want ErrInvalidParam", tc.name, err)
282			}
283			if errors.Is(err, ErrDuplicateID) {
284				t.Fatalf("%s: unregistered id must not report duplicate, got %v", tc.name, err)
285			}
286			if _, err := s.Product("pNew"); !errors.Is(err, ErrNotFound) {
287				t.Fatalf("%s: failed first registration left a record, got %v", tc.name, err)
288			}
289		}
290		// 同一编号随后以合法条款正常登记。
291		if err := s.RegisterProduct("pNew", t0, 30, []string{"FAULTX"}); err != nil {
292			t.Fatalf("register after failed attempts: %v", err)
293		}
294		checkProductTerms(t, s, "pNew", t0, 30, "FAULTX")
295		// 登记成功后再提交才报重复。
296		if err := s.RegisterProduct("pNew", t0, 30, []string{"FAULTX"}); !errors.Is(err, ErrDuplicateID) {
297			t.Fatalf("duplicate after successful registration: got %v, want ErrDuplicateID", err)
298		}
299	}
