93				d.CommitmentID, d.PartID, d.RequestID, d.OriginalQuantity, d.UsedQuantity, d.RemainingQuantity, d.Status, d.Expiry,
94				reconPartID, requestID, original, used, remaining, CommitmentActive, expiry)
