128		}
129		if d6.UsedQuantity+d6.RemainingQuantity != 6 {
130			t.Fatalf("c-six detail orig=%d used=%d rem=%d, want used+rem=6", d6.OriginalQuantity, d6.UsedQuantity, d6.RemainingQuantity)
131		}
132		assertReconDetail(t, d9, reconNineCommit, reconNineRequest, 9, d9.UsedQuantity, d9.RemainingQuantity, reconExpiryNine)
133		assertReconDetail(t, d6, reconSixCommit, reconSixRequest, 6, d6.UsedQuantity, d6.RemainingQuantity, reconExpirySix)
134	
135		usedTotal := d9.UsedQuantity + d6.UsedQuantity
136		unusedTotal := d9.RemainingQuantity + d6.RemainingQuantity
137		if st.ActiveOccupied != unusedTotal {
138			t.Fatalf("active occupied = %d, want sum of remaining quantities %d (details: %d/%d used)",
139				st.ActiveOccupied, unusedTotal, d9.UsedQuantity, d6.UsedQuantity)
140		}
141		if st.PhysicalRemaining != reconStock-usedTotal {
142			t.Fatalf("physical remaining = %d, want %d - used total %d",
143				st.PhysicalRemaining, reconStock, usedTotal)
144		}
145		if st.Committable != 5 {
146			t.Fatalf("committable = %d, want always 5", st.Committable)
147		}
148		if st.PhysicalRemaining-st.ActiveOccupied != st.Committable {
149			t.Fatalf("account does not reconcile: phys=%d occupied=%d committable=%d",
150				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
151		}
152		return d9.UsedQuantity, d6.UsedQuantity
153	}
154	
155	// assertReconReachable 断言查询看到的已用数量对应“某次正常使用处理前或处理
156	// 后”的完整状态：九件承诺的已用数量只能是 0、5、4、9（先五后四的任一先后
157	// 组合），六件承诺只能是 0、1、3、4（先一后三的任一先后组合）。任何其他
158	// 取值都意味着查询看到了只完成一半的扣减，即混用了不同阶段的数量。
159	func assertReconReachable(t *testing.T, usedNine, usedSix int) {
160		t.Helper()
161		switch usedNine {
162		case 0, 4, 5, 9:
163		default:
164			t.Fatalf("c-nine used = %d in a snapshot, want one of 0/4/5/9 (whole-use boundaries only)", usedNine)
165		}
166		switch usedSix {
167		case 0, 1, 3, 4:
168		default:
169			t.Fatalf("c-six used = %d in a snapshot, want one of 0/1/3/4 (whole-use boundaries only)", usedSix)
170		}
171	}
172	
173	// TestPartStatusBatchUseInterleavedSnapshots 顺序复现交错分批使用的完整过程：
174	// 初始 20/15/5；九件先用五件、六件先用一件后查询得 14/9/5；期间用新编号提交
175	// 十件被整次拒绝且数量不变；随后九件再用四件全部用完、六件再用三件共用四件，
176	// 查询得 7/2/5，已用完的承诺仍在明细中显示已用九件、未用零件。使用途中取得
177	// 并保留的两份结果不随后续使用变化。
178	func TestPartStatusBatchUseInterleavedSnapshots(t *testing.T) {
179		s := reconNewStore(t)
180	
181		// 查询开始前均未使用：实物剩余二十、有效占用十五、可承诺五。
182		before, err := s.PartStatus(reconPartID, nowOK)
183		if err != nil {
184			t.Fatalf("part status before uses: %v", err)
185		}
186		assertReconAccount(t, before, 20, 15, 5)
187		u9, u6 := assertReconSnapshotReconciles(t, before)
188		assertReconReachable(t, u9, u6)
189		assertReconDetail(t, before.Details[0], reconNineCommit, reconNineRequest, 9, 0, 9, reconExpiryNine)
190		assertReconDetail(t, before.Details[1], reconSixCommit, reconSixRequest, 6, 0, 6, reconExpirySix)
191	
192		// 交错分批使用：九件承诺先用五件，六件承诺先用一件。
193		if _, err := s.Use("u-nine-5", reconNineCommit, 5, nowOK); err != nil {
194			t.Fatalf("use 5 from c-nine: %v", err)
195		}
196		if _, err := s.Use("u-six-1", reconSixCommit, 1, nowOK); err != nil {
197			t.Fatalf("use 1 from c-six: %v", err)
198		}
199	
200		// 使用期间查询：实物 20-6=14，有效占用 4+5=9，可承诺仍为五。
201		mid, err := s.PartStatus(reconPartID, nowOK.Add(time.Minute))
202		if err != nil {
203			t.Fatalf("part status midway: %v", err)
204		}
205		assertReconAccount(t, mid, 14, 9, 5)
206		assertReconSnapshotReconciles(t, mid)
207		assertReconDetail(t, mid.Details[0], reconNineCommit, reconNineRequest, 9, 5, 4, reconExpiryNine)
208		assertReconDetail(t, mid.Details[1], reconSixCommit, reconSixRequest, 6, 1, 5, reconExpirySix)
209	
210		// 失败条件：用尚未成功过的编号向九件承诺提交十件（其未用仅四件）。
211		// 即使实物仍有十四件、另一笔承诺还有五件未用，也必须 ErrUsageExceeded
212		// 整次拒绝，返回空记录。
213		rejected, err := s.Use("u-bad-ten", reconNineCommit, 10, nowOK.Add(2*time.Minute))
214		if !errors.Is(err, ErrUsageExceeded) {
215			t.Fatalf("use 10 over unused 4: got %v, want ErrUsageExceeded", err)
216		}
217		if rejected != (Usage{}) {
218			t.Fatalf("rejected usage returned non-empty record: %+v", rejected)
219		}
220	
221		// 整次失败不扣减实物、不增加承诺已用数量：紧接查询与失败前完全一致。
222		afterReject, err := s.PartStatus(reconPartID, nowOK.Add(3*time.Minute))
223		if err != nil {
224			t.Fatalf("part status after rejected use: %v", err)
225		}
226		assertReconAccount(t, afterReject, 14, 9, 5)
227		assertReconDetail(t, afterReject.Details[0], reconNineCommit, reconNineRequest, 9, 5, 4, reconExpiryNine)
228		assertReconDetail(t, afterReject.Details[1], reconSixCommit, reconSixRequest, 6, 1, 5, reconExpirySix)
229		if c := mustCommitment(t, s, reconNineCommit); c.Used != 5 || c.Unused() != 4 || c.Canceled || c.Expired {
230			t.Fatalf("c-nine disturbed by rejected use: %+v", c)
231		}
232		if p, err := s.Part(reconPartID); err != nil || p.Stock != 14 {
233			t.Fatalf("physical stock after rejected use = %d (err %v), want 14", p.Stock, err)
234		}
235	
236		// 继续完成全部正常使用：九件再用四件（全部用完），六件再用三件（共用四件）。
237		if _, err := s.Use("u-nine-4", reconNineCommit, 4, nowOK.Add(4*time.Minute)); err != nil {
238			t.Fatalf("use 4 from c-nine: %v", err)
239		}
240		if _, err := s.Use("u-six-3", reconSixCommit, 3, nowOK.Add(5*time.Minute)); err != nil {
241			t.Fatalf("use 3 from c-six: %v", err)
242		}
243	
244		// 使用处理均已结束：实物剩余七件、有效占用两件、可承诺五件。已全部使用的
245		// 承诺仍在明细中，显示已用九件、未用零件，归属、原定数量与到期时刻不变。
246		final, err := s.PartStatus(reconPartID, nowOK.Add(6*time.Minute))
247		if err != nil {
248			t.Fatalf("final part status: %v", err)
249		}
250		assertReconAccount(t, final, 7, 2, 5)
251		assertReconSnapshotReconciles(t, final)
252		assertReconDetail(t, final.Details[0], reconNineCommit, reconNineRequest, 9, 9, 0, reconExpiryNine)
253		assertReconDetail(t, final.Details[1], reconSixCommit, reconSixRequest, 6, 4, 2, reconExpirySix)
254	
255		// 使用途中取得并保留的两份结果保留取得时的数量，不随后续使用变化。
256		assertReconAccount(t, before, 20, 15, 5)
257		assertReconDetail(t, before.Details[0], reconNineCommit, reconNineRequest, 9, 0, 9, reconExpiryNine)
258		assertReconDetail(t, before.Details[1], reconSixCommit, reconSixRequest, 6, 0, 6, reconExpirySix)
259		assertReconAccount(t, mid, 14, 9, 5)
260		assertReconDetail(t, mid.Details[0], reconNineCommit, reconNineRequest, 9, 5, 4, reconExpiryNine)
261		assertReconDetail(t, mid.Details[1], reconSixCommit, reconSixRequest, 6, 1, 5, reconExpirySix)
262	
263		// 仓库保存的事实与最终查询一致：失败的十件提交没有留下任何扣减。
264		if c := mustCommitment(t, s, reconNineCommit); c.Quantity != 9 || c.Used != 9 || c.Unused() != 0 || c.Canceled || c.Expired {
265			t.Fatalf("stored c-nine: %+v, want qty=9 used=9 unused=0 active", c)
266		}
267		if c := mustCommitment(t, s, reconSixCommit); c.Quantity != 6 || c.Used != 4 || c.Unused() != 2 || c.Canceled || c.Expired {
268			t.Fatalf("stored c-six: %+v, want qty=6 used=4 unused=2 active", c)
269		}
270		if p, err := s.Part(reconPartID); err != nil || p.Stock != 7 {
271			t.Fatalf("physical stock = %d (err %v), want 7", p.Stock, err)
272		}
273	}
274	
275	// reconFloodSpec 是并发洪泛中的一笔使用提交内容。
276	type reconFloodSpec struct {
277		usageID  string
278		commitID string
279		quantity int
280	}
281	
282	// reconFloodNormalSpecs 是四笔正常分批使用（两笔承诺各两批）。
283	var reconFloodNormalSpecs = []reconFloodSpec{
284		{"u-nine-5", reconNineCommit, 5},
285		{"u-nine-4", reconNineCommit, 4},
286		{"u-six-1", reconSixCommit, 1},
287		{"u-six-3", reconSixCommit, 3},
288	}
289	
290	// fanOutReconFlood 让四笔正常使用（每笔多个相同内容副本）、十件失败提交
291	// （多个副本）和大量 PartStatus 查询在同一道闸机释放后同时运行，尽量制造
292	// 查询与使用的交叉。返回各使用调用的结果和查询期间取得的全部快照。
293	func fanOutReconFlood(t *testing.T, s *Store, replicas, queryWorkers, queriesEach int) ([]concurrentUseResult, []*PartStatus) {
294		t.Helper()
295		specs := append([]reconFloodSpec{}, reconFloodNormalSpecs...)
296		specs = append(specs, reconFloodSpec{"u-bad-ten", reconNineCommit, 10})
297	
298		calls := make([]concurrentUseCall, 0, replicas*len(specs))
299		for rep := 0; rep < replicas; rep++ {
300			for k, sp := range specs {
301				// 各副本给不同但都早于到期时刻的当前时刻；当前时刻不属于使用编号
302				// 的绑定内容。
303				calls = append(calls, concurrentUseCall{
304					usageID:  sp.usageID,
305					commitID: sp.commitID,
306					quantity: sp.quantity,
307					now:      nowOK.Add(time.Duration(rep*len(specs)+k) * time.Minute),
308				})
309			}
310		}
311		results := make([]concurrentUseResult, len(calls))
312	
313		// 每个查询 goroutine 只写自己名下的切片，闸机等待结束后主 goroutine 才
314		// 读取，因此无需额外加锁。
315		workerSnapshots := make([][]*PartStatus, queryWorkers)
316		workerErrors := make([]error, queryWorkers)
317	
318		barrier := make(chan struct{})
319		var wg sync.WaitGroup
320		for i, c := range calls {
321			wg.Add(1)
322			go func(i int, c concurrentUseCall) {
323				defer wg.Done()
324				<-barrier
325				results[i].usage, results[i].err = s.Use(c.usageID, c.commitID, c.quantity, c.now)
326			}(i, c)
327		}
328		for w := 0; w < queryWorkers; w++ {
329			wg.Add(1)
330			go func(w int) {
331				defer wg.Done()
332				<-barrier
333				snaps := make([]*PartStatus, 0, queriesEach)
334				for q := 0; q < queriesEach; q++ {
335					// 查询时刻始终早于两笔到期时刻，承诺不发生到期确认。
336					st, err := s.PartStatus(reconPartID, nowOK.Add(time.Duration(w*queriesEach+q)*time.Second))
337					if err != nil {
338						workerErrors[w] = err
339						return
340					}
341					snaps = append(snaps, st)
342				}
343				workerSnapshots[w] = snaps
344			}(w)
345		}
346		close(barrier)
347		wg.Wait()
348	
349		for w, err := range workerErrors {
350			if err != nil {
351				t.Fatalf("concurrent part status query in worker %d: %v", w, err)
352			}
353		}
354		var snapshots []*PartStatus
355		for _, snaps := range workerSnapshots {
356			snapshots = append(snapshots, snaps...)
357		}
358		return results, snapshots
359	}
360	
361	// TestPartStatusQueriesConcurrentWithBatchUses 不规定查询与使用的完成先后：
362	// 四笔正常使用（相同内容并发副本只产生一次真实扣减）、十件失败提交（每个副本
363	// 都失败）与大量查询完全并发。每份查询都必须自洽（同一完整状态），且只能
364	// 观察到某次使用处理前或处理后的整数边界状态。全部结束后数量确定为 7/2/5。
365	func TestPartStatusQueriesConcurrentWithBatchUses(t *testing.T) {
366		const iterations = 6
367		for iter := 0; iter < iterations; iter++ {
368			s := reconNewStore(t)
369	
370			results, snapshots := fanOutReconFlood(t, s, 8, 8, 25)
371			if len(snapshots) == 0 {
372				t.Fatal("no snapshots captured")
373			}
374	
375			// 成功记录必须是四笔正常使用之一，数量、承诺与编号一一对应；其余调用
376			// （十件超量提交的全部相同内容副本）必须 ErrUsageExceeded 整次拒绝、
377			// 返回空记录。
378			for i, r := range results {
379				if r.err != nil {
380					if !errors.Is(r.err, ErrUsageExceeded) || r.usage != (Usage{}) {
381						t.Fatalf("iter %d call %d: usage=%+v err=%v, want ErrUsageExceeded with empty result", iter, i, r.usage, r.err)
382					}
383					continue
384				}
385				want, ok := mapUsageRecord(r.usage)
386				if !ok {
387					t.Fatalf("iter %d call %d: unexpected successful usage %+v", iter, i, r.usage)
388				}
389				if r.usage != want {
390					t.Fatalf("iter %d call %d: usage=%+v, want first record %+v", iter, i, r.usage, want)
391				}
392			}
393	
394			// 使用期间取得的每一份结果都必须内部自洽，且处于某个完整使用边界上。
395			for _, st := range snapshots {
396				u9, u6 := assertReconSnapshotReconciles(t, st)
397				assertReconReachable(t, u9, u6)
398			}
399	
400			// 全部处理结束：实物剩余七件、有效占用两件、可承诺五件。
401			final, err := s.PartStatus(reconPartID, nowOK.Add(time.Hour))
402			if err != nil {
403				t.Fatalf("iter %d final part status: %v", iter, err)
404			}
405			assertReconAccount(t, final, 7, 2, 5)
406			assertReconSnapshotReconciles(t, final)
407			assertReconDetail(t, final.Details[0], reconNineCommit, reconNineRequest, 9, 9, 0, reconExpiryNine)
408			assertReconDetail(t, final.Details[1], reconSixCommit, reconSixRequest, 6, 4, 2, reconExpirySix)
409	
410			// 仓库事实与最终查询一致。
411			if c := mustCommitment(t, s, reconNineCommit); c.Used != 9 || c.Unused() != 0 {
412				t.Fatalf("iter %d stored c-nine: %+v, want used=9 unused=0", iter, c)
413			}
414			if c := mustCommitment(t, s, reconSixCommit); c.Used != 4 || c.Unused() != 2 {
415				t.Fatalf("iter %d stored c-six: %+v, want used=4 unused=2", iter, c)
416			}
417			if p, err := s.Part(reconPartID); err != nil || p.Stock != 7 {
418				t.Fatalf("iter %d physical stock = %d (err %v), want 7", iter, p.Stock, err)
419			}
420	
421			// 调用方保留的快照不随最终状态变化：全部仍是取得时的完整状态。
422			for _, st := range snapshots {
423				assertReconSnapshotReconciles(t, st)
424			}
425		}
426	}
427	
428	// mapUsageRecord 判定一份成功使用记录是否对应四笔正常分批使用之一。
429	func mapUsageRecord(u Usage) (Usage, bool) {
430		for _, sp := range reconFloodNormalSpecs {
431			want := Usage{ID: sp.usageID, CommitmentID: sp.commitID, Quantity: sp.quantity}
432			if u == want {
433				return want, true
434			}
435		}
436		return Usage{}, false
437	}
438	
439	// TestPartStatusQueriesConcurrentWithRejectedTenPieceUse 在没有任何正常使用
440	// 介入时，让十件超量提交的多个副本与查询完全并发：九件承诺的未用数量始终为
441	// 九，十件提交无论先处理还是后处理都必须 ErrUsageExceeded，期间每份查询都
442	// 保持初始的 20/15/5，失败提交不造成实物扣减或已用数量增加。
443	func TestPartStatusQueriesConcurrentWithRejectedTenPieceUse(t *testing.T) {
444		const iterations = 6
445		for iter := 0; iter < iterations; iter++ {
446			s := reconNewStore(t)
447	
448			const submitters = 12
449			results := make([]concurrentUseResult, submitters)
450			const queryWorkers, queriesEach = 8, 20
451			workerSnapshots := make([][]*PartStatus, queryWorkers)
452			workerErrors := make([]error, queryWorkers)
453	
454			barrier := make(chan struct{})
455			var wg sync.WaitGroup
456			for i := 0; i < submitters; i++ {
457				wg.Add(1)
458				go func(i int) {
459					defer wg.Done()
460					<-barrier
461					results[i].usage, results[i].err = s.Use(
462						"u-bad-ten", reconNineCommit, 10,
463						nowOK.Add(time.Duration(i)*time.Minute))
464				}(i)
465			}
466			for w := 0; w < queryWorkers; w++ {
467				wg.Add(1)
468				go func(w int) {
469					defer wg.Done()
470					<-barrier
471					snaps := make([]*PartStatus, 0, queriesEach)
472					for q := 0; q < queriesEach; q++ {
473						st, err := s.PartStatus(reconPartID, nowOK.Add(time.Duration(w*queriesEach+q)*time.Second))
474						if err != nil {
475							workerErrors[w] = err
476							return
477						}
478						snaps = append(snaps, st)
479					}
480					workerSnapshots[w] = snaps
481				}(w)
482			}
483			close(barrier)
484			wg.Wait()
485	
486			for w, err := range workerErrors {
487				if err != nil {
488					t.Fatalf("iter %d query worker %d: %v", iter, w, err)
489				}
490			}
491	
492			// 同一个新编号的全部并发提交都按超量使用整次拒绝；编号未被占用，
493			// 不会有任何一份“抢先成功”。
494			for i, r := range results {
495				if !errors.Is(r.err, ErrUsageExceeded) || r.usage != (Usage{}) {
496					t.Fatalf("iter %d submitter %d: usage=%+v err=%v, want ErrUsageExceeded with empty result",
497						iter, i, r.usage, r.err)
498				}
499			}
500	
501			// 与查询谁先处理都一样：期间每份结果都是初始的 20/15/5 完整状态。
502			var count int
503			for _, snaps := range workerSnapshots {
504				for _, st := range snaps {
505					count++
506					assertReconAccount(t, st, 20, 15, 5)
507					assertReconSnapshotReconciles(t, st)
508					assertReconDetail(t, st.Details[0], reconNineCommit, reconNineRequest, 9, 0, 9, reconExpiryNine)
509					assertReconDetail(t, st.Details[1], reconSixCommit, reconSixRequest, 6, 0, 6, reconExpirySix)
510				}
511			}
512			if count == 0 {
513				t.Fatalf("iter %d: no snapshots captured", iter)
514			}
515	
516			// 结束后承诺与实物库存保持初始值。
517			if c := mustCommitment(t, s, reconNineCommit); c.Used != 0 || c.Unused() != 9 || c.Canceled || c.Expired {
518				t.Fatalf("iter %d c-nine after rejected flood: %+v, want used=0 unused=9 active", iter, c)
519			}
520			if c := mustCommitment(t, s, reconSixCommit); c.Used != 0 || c.Unused() != 6 {
521				t.Fatalf("iter %d c-six after rejected flood: %+v, want used=0 unused=6", iter, c)
522			}
523			if p, err := s.Part(reconPartID); err != nil || p.Stock != 20 {
524				t.Fatalf("iter %d physical stock = %d (err %v), want 20", iter, p.Stock, err)
525			}
526		}
527	}
