14	// nyc 返回美国纽约时区（2026 年春进为 3 月 8 日、秋退为 11 月 1 日）。
15	func nyc(t *testing.T) *time.Location {
16		t.Helper()
17		loc, err := time.LoadLocation("America/New_York")
18		if err != nil {
19			t.Fatalf("load America/New_York: %v", err)
20		}
21		return loc
22	}
