24	// dstCase 描述一次跨越夏令时切换的一天期保修。
25	type dstCase struct {
26		name        string
27		purchase    time.Time
28		purchaseOff int // 购买时刻的 UTC 偏移（秒）
29		expMonth    time.Month
30		expDay      int
31		expHour     int
32		expMinute   int
33		expOff      int // 保修截止时刻的 UTC 偏移（秒）
34		expZone     string
35		// 次日钟面陷阱时刻：春进时次日十二点（早于十三点截止）仍应合格；
36		// 秋退时刻度尚未回到购买时的十二点（如十一点半）也应已过保。
37		clockTrap     time.Time
38		clockTrapElig bool
39	}
40	
41	func dstCases(t *testing.T) []dstCase {
42		loc := nyc(t)
43		return []dstCase{
44			{
45				name:          "spring_forward",
46				purchase:      time.Date(2026, time.March, 7, 12, 0, 0, 123456789, loc),
47				purchaseOff:   -5 * 3600, // EST
48				expMonth:      time.March,
49				expDay:        8,
50				expHour:       13, // 当地只有 23 小时：钟面截止时刻被推到十三点
51				expMinute:     0,
52				expOff:        -4 * 3600, // EDT
53				expZone:       "EDT",
54				clockTrap:     time.Date(2026, time.March, 8, 12, 0, 0, 0, loc),
55				clockTrapElig: true, // 次日十二点距离购买只过了 23 小时，不能提前认定过保
56			},
57			{
58				name:          "fall_back",
59				purchase:      time.Date(2026, time.October, 31, 12, 0, 0, 123456789, loc),
60				purchaseOff:   -4 * 3600, // EDT
61				expMonth:      time.November,
62				expDay:        1,
63				expHour:       11, // 当地有 25 小时：钟面截止时刻提前到十一点
64				expMinute:     0,
65				expOff:        -5 * 3600, // EST
66				expZone:       "EST",
67				clockTrap:     time.Date(2026, time.November, 1, 11, 30, 0, 0, loc),
68				clockTrapElig: false, // 钟面尚未回到购买时的十二点，但实际已满 24 小时
69			},
70		}
71	}
72	
73	// 注册一个一天期、故障 NOISE 不在除外清单的产品及请求，返回保修截止时刻。
74	func registerOneDayWarranty(t *testing.T, s *Store, purchase time.Time) time.Time {
75		t.Helper()
76		if err := s.RegisterProduct("p", purchase, 1, nil); err != nil {
77			t.Fatalf("register product: %v", err)
78		}
79		if err := s.SubmitRequest("r", "p", "NOISE"); err != nil {
80			t.Fatalf("submit request: %v", err)
81		}
82		e, err := s.Evaluate("r", purchase)
83		if err != nil {
84			t.Fatalf("evaluate at purchase: %v", err)
85		}
86		if !e.Eligible {
87			t.Fatalf("purchase instant must be eligible, reasons %v", e.Reasons)
88		}
89		return e.WarrantyExpiry
90	}
91	
92	// TestWarrantyDSTOneDayAlwaysTwentyFourHours 覆盖时钟向前和向后调整两种
93	// 购买条件：保修一天的截止时刻都是购买时刻之后完整二十四小时的实际时刻，
94	// 不因为当地一天只有二十三小时或二十五小时而提前或推后；截止时刻保留购买
95	// 时刻的时区表示与小数秒精度，不取整到整秒、整点或当天零点。
96	func TestWarrantyDSTOneDayAlwaysTwentyFourHours(t *testing.T) {
97		for _, tc := range dstCases(t) {
98			t.Run(tc.name, func(t *testing.T) {
99				s := NewStore()
100				expiry := registerOneDayWarranty(t, s, tc.purchase)
101	
102				if name, off := tc.purchase.Zone(); off != tc.purchaseOff {
103					t.Fatalf("purchase offset = %s(%d), want %d", name, off, tc.purchaseOff)
104				}
105				// 实际跨度必须正好二十四小时：Unix 秒差 86400，纳秒差也为 0。
106				if got := expiry.Sub(tc.purchase); got != 24*time.Hour {
107					t.Fatalf("actual warranty length = %v, want 24h", got)
108				}
109				if got := expiry.Unix() - tc.purchase.Unix(); got != secondsPerDay {
110					t.Fatalf("actual warranty length = %d seconds, want %d", got, secondsPerDay)
111				}
112	
113				loc := nyc(t)
114				got := expiry.In(loc)
115				if got.Year() != 2026 || got.Month() != tc.expMonth || got.Day() != tc.expDay ||
116					got.Hour() != tc.expHour || got.Minute() != tc.expMinute || got.Second() != 0 {
117					t.Fatalf("expiry clock = %v, want 2026-%02d-%02d %02d:%02d:00",
118						got.Format("2006-01-02 15:04:05"), tc.expMonth, tc.expDay, tc.expHour, tc.expMinute)
119				}
120				if name, off := got.Zone(); name != tc.expZone || off != tc.expOff {
121					t.Fatalf("expiry zone = %s(%d), want %s(%d)", name, off, tc.expZone, tc.expOff)
122				}
123				// 小数秒原样保留在截止时刻。
124				if got.Nanosecond() != tc.purchase.Nanosecond() || got.Nanosecond() != 123456789 {
125					t.Fatalf("sub-second precision lost: expiry nanos = %d, purchase = %d",
126						got.Nanosecond(), tc.purchase.Nanosecond())
127				}
128	
129				e, err := s.Evaluate("r", tc.purchase)
130				if err != nil {
131					t.Fatal(err)
132				}
133				if !e.PurchaseTime.Equal(tc.purchase) || e.WarrantyDays != 1 {
134					t.Fatalf("basis = (%v, %d days), want (%v, 1)", e.PurchaseTime, e.WarrantyDays, tc.purchase)
135				}
136			})
137		}
138	}
139	
140	// alternativeZones 返回同一实际时刻的不同文字表示：纽约本地、协调世界时，
141	// 以及日期/小时完全不同的两个固定偏移（秋退截止时刻 16:00Z 在 UTC+8 已是
142	// 次日零点）。结论不得因表示不同而改变。
143	func alternativeZones(t *testing.T) []*time.Location {
144		return []*time.Location{
145			nyc(t),
146			time.UTC,
147			time.FixedZone("UTC+8", 8*3600),
148			time.FixedZone("UTC-8", -8*3600),
149		}
150	}
151	
152	func reasonsEqual(a, b []RejectionReason) bool {
153		if len(a) != len(b) {
154			return false
155		}
156		for i := range a {
157			if a[i] != b[i] {
158				return false
159			}
160		}
161		return true
162	}
163	
164	// TestWarrantyDSTEligibilityBoundaryAndZoneRepresentation 验证两种切换下：
165	// 截止前一纳秒仍合格；恰好到达截止时刻及之后过保，拒绝原因明确只有保修已
166	// 到期；同一查询时刻换协调世界时或其他时区表示，资格结果与实际截止时刻一致。
167	func TestWarrantyDSTEligibilityBoundaryAndZoneRepresentation(t *testing.T) {
168		for _, tc := range dstCases(t) {
169			t.Run(tc.name, func(t *testing.T) {
170				s := NewStore()
171				expiry := registerOneDayWarranty(t, s, tc.purchase)
172	
173				before := expiry.Add(-time.Nanosecond)
174				at := expiry
175				after := expiry.Add(time.Nanosecond)
176	
177				for _, z := range alternativeZones(t) {
178					t.Run(z.String(), func(t *testing.T) {
179						// 截止前一纳秒：合格，无拒绝原因。
180						e, err := s.Evaluate("r", before.In(z))
181						if err != nil {
182							t.Fatalf("evaluate 1ns before: %v", err)
183						}
184						if !e.Eligible || len(e.Reasons) != 0 {
185							t.Fatalf("1ns before expiry: %+v", e)
186						}
187						if !e.WarrantyExpiry.Equal(expiry) {
188							t.Fatalf("expiry instant %v drifted with query zone %s", e.WarrantyExpiry, z)
189						}
190	
191						// 恰好到达截止时刻：过保，原因明确为保修已到期。
192						eAt, err := s.Evaluate("r", at.In(z))
193						if err != nil {
194							t.Fatalf("evaluate at expiry: %v", err)
195						}
196						if eAt.Eligible || !reasonsEqual(eAt.Reasons, []RejectionReason{ReasonWarrantyExpired}) {
197							t.Fatalf("at expiry: %+v", eAt)
198						}
199						if !eAt.WarrantyExpiry.Equal(expiry) {
200							t.Fatalf("expiry instant %v drifted with query zone %s", eAt.WarrantyExpiry, z)
201						}
202	
203						// 截止之后一纳秒：同样过保。
204						eAfter, err := s.Evaluate("r", after.In(z))
205						if err != nil {
206							t.Fatalf("evaluate after expiry: %v", err)
207						}
208						if eAfter.Eligible || !reasonsEqual(eAfter.Reasons, []RejectionReason{ReasonWarrantyExpired}) {
209							t.Fatalf("after expiry: %+v", eAfter)
210						}
211						if !eAfter.WarrantyExpiry.Equal(eAt.WarrantyExpiry) {
212							t.Fatalf("expiry instants differ across query times/zones")
213						}
214					})
215				}
216	
217				// 钟面陷阱：按当地钟面小时而非实际经过时间判断就会得出错误结论。
218				e, err := s.Evaluate("r", tc.clockTrap)
219				if err != nil {
220					t.Fatal(err)
221				}
222				if e.Eligible != tc.clockTrapElig {
223					t.Fatalf("clock-face trap at %v: eligible=%v, want %v, reasons %v",
224						tc.clockTrap, e.Eligible, tc.clockTrapElig, e.Reasons)
225				}
226				if tc.clockTrapElig {
227					if len(e.Reasons) != 0 {
228						t.Fatalf("spring-forward next noon must be eligible, reasons %v", e.Reasons)
229					}
230				} else if !containsReason(e.Reasons, ReasonWarrantyExpired) {
231					t.Fatalf("fall-back 11:30 wall clock must be expired, reasons %v", e.Reasons)
232				}
233			})
234		}
235	}
